export const ratingValues=['unknown','supported','independent'];
export const textFields=['goal','prediction','attempt','change','support','childVoice','adultReflection','next'];
export function localDate(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
export function validDate(s){return typeof s==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s)&&!Number.isNaN(Date.parse(s))&&new Date(s+'T00:00:00Z').toISOString().slice(0,10)===s&&s<=localDate();}
export function validateSession(s,cases){const c=cases.find(a=>a.id===s?.caseId);if(!c||!validDate(s.date)||!Array.isArray(s.rows)||s.rows.length!==3)return false;if(c.custom&&(typeof s.custom?.title!=='string'||!s.custom.title.trim()||s.custom.title.length>160))return false;const narrative=c.custom&&typeof s.fields?.attempt==='string'&&s.fields.attempt.trim().length>0;return s.rows.every(r=>r&&ratingValues.includes(r.rating)&&typeof r.evidence==='string'&&r.evidence.length<=3000)&&(narrative||s.rows.some(r=>r.rating!=='unknown'))&&s.rows.every(r=>r.rating==='unknown'||r.evidence.trim().length>0);}
export function sanitizeSession(s,cases){if(!validateSession(s,cases)||typeof s.id!=='string'||(!s.id.length||s.id.length>120)||!s.fields||typeof s.fields!=='object')return null;const fields={};for(const key of textFields)fields[key]=typeof s.fields[key]==='string'?s.fields[key].slice(0,3000):'';const custom=cases.find(c=>c.id===s.caseId)?.custom?{title:s.custom.title.trim(),materials:typeof s.custom.materials==='string'?s.custom.materials.slice(0,3000):'',plan:typeof s.custom.plan==='string'?s.custom.plan.slice(0,3000):''}:undefined;return{custom,id:s.id,caseId:s.caseId,date:s.date,age:Number.isInteger(s.age)&&s.age>=5&&s.age<=16?s.age:8,fields,rows:s.rows.map(r=>({rating:r.rating,evidence:r.evidence.slice(0,3000)})),createdAt:typeof s.createdAt==='string'?s.createdAt:'',updatedAt:typeof s.updatedAt==='string'?s.updatedAt:''};}
export function summarizeSessions(sessions,cases){const stats={sessions:sessions.length,skills:0,independent:0,supported:0,unknown:0,bySkill:[],evidence:[]};const map=new Map();for(const s of sessions){const c=cases.find(a=>a.id===s.caseId);if(!c)continue;if(!map.has(c.skillId))map.set(c.skillId,{id:c.skillId,name:c.skillName,custom:!!c.custom,sessions:0,dates:new Set(),independent:0,supported:0,unknown:0,examples:[],independentSessions:new Set(),independentDates:new Set()});const skill=map.get(c.skillId);skill.sessions++;skill.dates.add(s.date);s.rows.forEach((r,i)=>{if(!ratingValues.includes(r.rating))return;stats[r.rating]++;skill[r.rating]++;if(r.rating==='independent'){skill.independentSessions.add(s.id);skill.independentDates.add(s.date);}if(r.rating!=='unknown'){const e={sessionId:s.id,date:s.date,caseId:s.caseId,skillId:c.skillId,criterion:c.observations[i],rating:r.rating,evidence:r.evidence};stats.evidence.push(e);skill.examples.push(e);}});}stats.bySkill=[...map.values()].map(s=>({...s,dates:[...s.dates].sort(),independentSessions:s.independentSessions.size,independentDates:[...s.independentDates].sort()}));stats.skills=stats.bySkill.filter(s=>!s.custom).length;stats.observed=stats.independent+stats.supported;return stats;}
export function mergeBackup(current,backup,cases){if(backup?.format!=='learning-together-v2'||!Array.isArray(backup.sessions)||backup.sessions.length>10000)throw new Error('Invalid backup');const incoming=backup.sessions.map(s=>sanitizeSession(s,cases));if(incoming.some(s=>!s))throw new Error('Invalid session');const map=new Map(current.map(s=>[s.id,s]));for(const s of incoming)if(!map.has(s.id))map.set(s.id,s);return [...map.values()];}
export function escapeHtml(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
